export async function createNativeExecution(ctx:Context,hostIO:NativeHostIO=nativeHostIO,webWire:OfficialWebWireTransport=officialWebWire):Promise<ExecutionPort|undefined> {
    installNativeOwnershipFence(ctx);
    if(!ctx.get('agents')||!ctx.get('llm')||!ctx.get('sessions')||!ctx.get('tools')||!ctx.get('settings')||!ctx.get('credentials')||!ctx.get('configEditor'))return undefined;
    let execution:NativeExecution|undefined;
    await ctx.plugin({name:'role-native-execution',inject:['agents','llm','sessions','tools','settings','credentials','configEditor','spillStore'],apply(c:Context){execution=new NativeExecution(c,hostIO,webWire);execution.install(c);}});
    return execution;
}
